<script setup lang="ts">
import { computed, onUnmounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { api } from './api'
import PendingDeployment from './PendingDeployment.vue'
import { scopeLabel } from './monitoring'
import { privateKeyFileReader, maxPrivateKeyBytes } from './privateKeyFile'
import { errorMessage, requestKey, type Settings, type Preview, type Job, type UpgradePreview } from './monitoring'
const props = defineProps<{ modelValue: boolean; nodeId: string }>(), emit = defineEmits<{ 'update:modelValue': [boolean]; saved: [] }>()
const router = useRouter(), settings = ref<Settings>(), error = ref(''), busy = ref(false), preview = ref<Preview>()
const form = reactive({ id: '', name: '', host: '', enabled: true, mode: 'native', port: 22, auth: 'key', key: '', keySource: 'path', keyContent: '', keyConfigured: false, password: '', override: false, roots: '', extensions: '', excludes: '' })
const connection=ref<{ok:boolean;items:{name:string;status:string;message:string}[]}>(),checking=ref(false)
const publicMonitor=computed(()=>((settings.value?.values.node_defaults||{}) as Record<string,unknown>).monitor as Record<string,unknown>||{})
let customDraft=false
function overrideChanged(value:unknown){if(value && !customDraft){copyRoots();customDraft=true}}
async function checkConnection(){if(checking.value||busy.value)return;checking.value=true;error.value='';connection.value=undefined;const current=dialogVersion,draft=draftVersion;try{validateContent();const result=await api<{ok:boolean;items:{name:string;status:string;message:string}[]}>('/api/servers/preflight','POST',edit());if(current===dialogVersion&&draft===draftVersion&&props.modelValue)connection.value=result}catch(e){if(current===dialogVersion&&draft===draftVersion&&props.modelValue)error.value=errorMessage(e)}finally{checking.value=false}}
const upgrade = ref<UpgradePreview>(), upgradeDraft=ref(false)
const deployed=computed(()=>settings.value?.node_deployments?.[props.nodeId])
const savedNode=computed(()=>settings.value?.effective_nodes.find(n=>n.id===props.nodeId))
const canUpgrade=computed(()=>!!props.nodeId&&savedNode.value?.enabled!==false&&['complete','go-rolled-back'].includes(deployed.value?.phase||'')&&!!deployed.value?.version)
async function previewUpgrade(){if(busy.value)return;busy.value=true;error.value='';const current=dialogVersion;try{const result=await api<UpgradePreview>(`/api/servers/${encodeURIComponent(props.nodeId)}/upgrade-preview`,'POST',{revision:settings.value?.revision});if(current===dialogVersion&&props.modelValue){upgrade.value=result;upgradeDraft.value=!!preview.value||draftVersion>loadedDraftVersion}}catch(e){if(current===dialogVersion&&props.modelValue)error.value=errorMessage(e)}finally{busy.value=false}}
async function runUpgrade(){if(busy.value||!upgrade.value?.preview_token)return;busy.value=true;error.value='';try{const job=await api<Job>('/api/deployments','POST',{request_key:requestKey(),revision:upgrade.value.revision,kind:'upgrade-node',node:props.nodeId,preview_token:upgrade.value.preview_token});emit('update:modelValue',false);emit('saved');await router.push(`/deployments/${job.id}`)}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
let loadedDraftVersion=0
const reading=ref(false), fileInput=ref<HTMLInputElement>()
let dialogVersion=0, draftVersion=0
watch(form,()=>{draftVersion++;preview.value=undefined;connection.value=undefined},{deep:true,flush:'sync'})
const keyReader=privateKeyFileReader(value=>{form.keyContent=value;preview.value=undefined;error.value=''},message=>{error.value=message},value=>{reading.value=value})
function filesSelected(event:Event){const input=event.target as HTMLInputElement;const files=Array.from(input.files||[]);input.value='';if(files.length&&!busy.value)void keyReader.read(files)}
function dropped(event:DragEvent){if(!busy.value)void keyReader.read(Array.from(event.dataTransfer?.files||[]))}
function keySourceChanged(){keyReader.cancel();form.keyContent='';preview.value=undefined;error.value=''}
watch(()=>form.auth,()=>{keyReader.cancel();form.keyContent='';preview.value=undefined})
onUnmounted(()=>{dialogVersion++;keyReader.cancel();form.keyContent=''})
watch(() => props.modelValue, async value => { const current=++dialogVersion;upgrade.value=undefined;keyReader.cancel();form.keyContent='';connection.value=undefined;customDraft=false;if (!value) return; error.value = ''; preview.value = undefined; try { const loaded=await api<Settings>('/api/settings'); if(current!==dialogVersion||!props.modelValue)return;settings.value=loaded;const nodes = (settings.value.values.nodes || []) as Record<string, unknown>[]; const n = nodes.find(n => n.id === props.nodeId); const effective = settings.value.effective_nodes.find(n => n.id === props.nodeId); const ssh = {...((effective?.ssh || {}) as Record<string,unknown>),...((n?.ssh || {}) as Record<string, unknown>)}, monitor = {...((effective?.monitor || {}) as Record<string,unknown>),...((n?.monitor || {}) as Record<string,unknown>)};customDraft=!!n?.monitor; Object.assign(form, { id: n?.id || '', name: n?.name || '', host: n?.host || '', enabled: n?.enabled ?? true, mode: ((effective?.deployment || n?.deployment || {}) as Record<string, unknown>).mode || 'native', port: ssh.port || 22, auth: ssh.auth_method || 'key', key: ssh.private_key_path || '', keySource:'path',keyContent:'',keyConfigured:!!(ssh.private_key_path_configured||ssh.private_key_path),password: '', override: !!n?.monitor, roots: ((monitor.roots || []) as string[]).join('\n'), extensions: ((monitor.extensions || []) as string[]).join('\n'), excludes: ((monitor.exclude_paths || []) as string[]).join('\n') });loadedDraftVersion=draftVersion } catch (e) { if(current===dialogVersion&&props.modelValue)error.value = errorMessage(e) } })
function lines(v: string) { return v.split('\n').map(v => v.trim()).filter(Boolean) }
function edit() { const node: Record<string, unknown> = { id: form.id.trim(), name: form.name.trim(), host: form.host.trim(), enabled: form.enabled, deployment: { mode: form.mode }, ssh: { username: 'root', port: Number(form.port), auth_method: form.auth, private_key_path: form.auth==='key'&&form.keySource==='path'?form.key.trim():'', password: form.password } }; if (form.override) node.monitor = { roots: lines(form.roots), extensions: lines(form.extensions), exclude_paths: lines(form.excludes) }; else node.monitor = null; return { revision: settings.value?.revision || '', patch: {}, node_id: props.nodeId, node, ssh_private_key_content:form.auth==='key'&&form.keySource==='content'?form.keyContent:undefined } }
function validateContent(){if(reading.value)throw new Error('私钥文件正在读取，请稍候');if(form.auth==='key'&&form.keySource==='content'&&new TextEncoder().encode(form.keyContent).length>maxPrivateKeyBytes)throw new Error('私钥内容不能超过 64 KiB')}
async function inspect() { if(busy.value)return;busy.value = true; error.value = ''; const current=dialogVersion,draft=draftVersion;try { validateContent();preview.value = undefined;const result = await api<Preview>('/api/settings/preview', 'POST', edit());if(current===dialogVersion&&draft===draftVersion&&props.modelValue)preview.value=result } catch (e) { if(current===dialogVersion&&draft===draftVersion&&props.modelValue)error.value = errorMessage(e) } finally { busy.value = false } }
async function save(deploy: boolean) { if(busy.value)return;busy.value = true; error.value = ''; try { validateContent();if (deploy) { const job = await api<Job>('/api/deployments', 'POST', { request_key: requestKey(), revision: settings.value?.revision, kind: 'add-node', node: form.id, edit: edit() }); emit('update:modelValue', false); emit('saved'); await router.push(`/deployments/${job.id}`) } else { await api('/api/settings', 'PUT', edit()); emit('update:modelValue', false); emit('saved') } } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
function copyRoots() { const defaults = ((settings.value?.values.node_defaults || {}) as Record<string, unknown>).monitor as Record<string, unknown> | undefined; form.roots = ((defaults?.roots || []) as string[]).join('\n'); form.extensions = ((defaults?.extensions || []) as string[]).join('\n'); form.excludes = ((defaults?.exclude_paths || []) as string[]).join('\n') }
</script>
<template><el-dialog class="node-editor-dialog" :model-value="modelValue" :title="nodeId ? '编辑子服务器' : '添加子服务器'" width="min(720px, 96vw)" @update:model-value="emit('update:modelValue', $event)"><el-alert v-if="error" :title="error" type="error" :closable="false" /><PendingDeployment :recovery="settings?.recovery"/><el-form label-position="top" :disabled="busy || checking" @input="preview = undefined"><p v-if="nodeId" class="muted">当前版本：{{deployed?.version||'未知'}} · 运行方式：{{deployed?.mode==='docker'?'Docker':deployed?.mode==='native'?'直接运行 Go':'未知'}}</p><h3>基本信息</h3><div class="form-grid"><el-form-item label="名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="唯一节点 ID"><el-input v-model="form.id" :disabled="!!nodeId" placeholder="node-example" /></el-form-item><el-form-item label="服务器 IP"><el-input v-model="form.host" :disabled="!!nodeId" /></el-form-item><el-form-item label="SSH 端口（root 用户）"><el-input v-model="form.port" type="number" /></el-form-item></div><h3>部署方式</h3><el-form-item label="部署方式"><el-select v-model="form.mode" @change="preview = undefined"><el-option label="直接运行 Go（无需 Docker）" value="native" /><el-option label="Docker 单容器" value="docker" /></el-select><small class="muted">切换前备份配置与数据库，保留网站文件、扫描任务和待投递事件。Docker 模式缺少引擎时会在支持的系统自动安装。</small></el-form-item><el-form-item label="启用节点"><el-switch v-model="form.enabled" /><small class="muted">停用只保存配置；到系统设置应用后停止中心采集与告警，节点数据保留。</small></el-form-item><h3>连接认证</h3><el-form-item label="认证方式"><el-select v-model="form.auth"><el-option label="主服务器私钥" value="key" /><el-option label="SSH 密码" value="password" /></el-select></el-form-item><template v-if="form.auth === 'key'"><el-form-item label="私钥来源"><el-radio-group v-model="form.keySource" @change="keySourceChanged"><el-radio value="path">主服务器路径</el-radio><el-radio value="content">私钥内容</el-radio></el-radio-group></el-form-item><p v-if="form.keyConfigured" class="muted">私钥已配置，留空保留；已有私钥内容不会回显。</p><el-form-item v-if="form.keySource==='path'" label="主服务器私钥绝对路径"><el-input v-model="form.key" placeholder="/root/.ssh/node-example" /></el-form-item><el-form-item v-else label="私钥内容"><div class="private-key-entry" @dragover.prevent @drop.prevent.stop="dropped"><el-input v-model="form.keyContent" data-testid="private-key-content" type="textarea" :rows="6" @input="keyReader.cancel()" autocomplete="off" spellcheck="false" placeholder="拖入私钥文件，或在这里粘贴未加密的 OpenSSH / PEM 私钥" /><div class="private-key-actions"><input ref="fileInput" data-testid="private-key-file" type="file" hidden @change="filesSelected"/><el-button :disabled="busy" @click="fileInput?.click()">选择私钥文件</el-button><span class="muted">{{reading?'正在读取文件…':'每次一个文件，最大 64 KiB；读取后请校验并预览。'}}</span></div></div></el-form-item></template><el-form-item v-else label="SSH 密码（已有密码留空保留）"><el-input v-model="form.password" type="password" autocomplete="new-password" /></el-form-item><h3>文件监控</h3><el-form-item label="监控配置来源"><el-radio-group v-model="form.override" @change="overrideChanged"><el-radio :value="false">使用公共配置（推荐）</el-radio><el-radio :value="true">为此服务器单独配置</el-radio></el-radio-group></el-form-item><div v-if="!form.override" class="inherited-monitor"><p class="muted">跟随公共配置，应用修改后生效。</p><p>监控目录：{{(publicMonitor.roots as string[]||[]).join('、')||'未配置'}}</p><p>文件后缀：{{(publicMonitor.extensions as string[]||[]).join('、')||'全部文件'}}</p><p>忽略规则：{{(publicMonitor.exclude_paths as string[]||[]).join('、')||'无'}}</p></div><div v-if="form.override"><p class="muted">下列列表整体替换公共值，后续独立维护；未展示的高级规则继续按原配置继承。</p><el-button @click="copyRoots">复制公共配置</el-button><el-form-item label="根目录，每行一个"><el-input v-model="form.roots" type="textarea" :rows="3" /></el-form-item><el-form-item label="后缀，每行一个"><el-input v-model="form.extensions" type="textarea" :rows="3" /></el-form-item><el-form-item label="忽略规则，每行一个"><el-input v-model="form.excludes" type="textarea" :rows="3" /></el-form-item></div><p class="muted">SSH 指纹自动记录。部署只处理所选节点；网站历史和其他节点继续保留。</p></el-form><el-alert v-if="preview" :title="`校验通过：${preview.restart ? '需要部署对应服务' : '无需重建'}；范围 ${scopeLabel(preview.scope)}`" type="success" :closable="false" /><p v-if="preview" class="muted">{{(preview.changes||[]).filter(change=>change.field.endsWith('.ssh.private_key')).map(change=>`私钥：${change.after}`).join('；')}}</p><el-card v-if="connection" shadow="never"><strong>{{connection.ok?'连接与环境检查完成':'存在未通过的检查'}}</strong><p v-for="(item,index) in connection.items" :key="index"><el-tag :type="item.status==='passed'?'success':item.status==='failed'?'danger':'info'">{{item.status==='passed'?'通过':item.status==='failed'?'未通过':'待部署验收'}}</el-tag> {{item.name}}：{{item.message}}</p></el-card><el-card v-if="upgrade" shadow="never"><h3>升级子服务器预览</h3><p>{{upgrade.scope}}</p><el-alert title="本次使用已保存配置，不保存弹窗草稿。切换部署方式请使用保存并部署。" type="warning" :closable="false"/><p v-if="upgradeDraft" class="muted">弹窗中有未保存修改，本次升级不包含这些修改。</p><p>当前版本：{{upgrade.current_version||'未知'}} → 目标版本：{{upgrade.target_version}} · {{upgrade.mode==='docker'?'Docker':'直接运行 Go'}}</p><p class="upgrade-digest">目标摘要：{{upgrade.target_image}}</p><p v-if="!upgrade.baseline_known" class="muted">缺少旧应用基线，无法确认配置差异。</p><p v-for="change in upgrade.changes" :key="change.field" class="upgrade-digest">{{change.field}}：{{change.before}} → {{change.after}}</p><el-alert v-if="upgrade.no_change" title="已是相同版本和摘要，且配置已应用，无需升级" type="success" :closable="false"/></el-card><template #footer><el-button @click="emit('update:modelValue', false)">取消</el-button><el-button v-if="canUpgrade" :loading="busy" :disabled="checking||settings?.pending_task" @click="previewUpgrade">升级子服务器</el-button><el-button v-if="upgrade?.preview_token" type="warning" :loading="busy" :disabled="checking||settings?.pending_task" @click="runUpgrade">确认升级（不保存草稿）</el-button><el-button :loading="checking" :disabled="busy||reading||settings?.pending_task" @click="checkConnection">连接与环境检查</el-button><el-button :loading="busy" :disabled="reading||checking||settings?.pending_task" @click="inspect">校验并预览</el-button><el-button v-if="preview" :loading="busy" :disabled="reading||checking||settings?.pending_task" @click="save(false)">仅保存</el-button><el-button v-if="preview && form.enabled" type="primary" :loading="busy" :disabled="reading||checking||settings?.pending_task" @click="save(true)">保存并部署</el-button></template></el-dialog></template>

<style>
.node-editor-dialog.el-dialog{display:flex;flex-direction:column;max-height:calc(100dvh - 32px);margin:16px auto!important;overflow:hidden}
.node-editor-dialog>.el-dialog__header,.node-editor-dialog>.el-dialog__footer{flex-shrink:0}
.node-editor-dialog>.el-dialog__body{overflow-y:auto;min-height:0;overflow-wrap:anywhere}
.node-editor-dialog>.el-dialog__footer{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px;border-top:1px solid var(--el-border-color-lighter);padding-top:12px}
.node-editor-dialog>.el-dialog__footer .el-button+.el-button{margin-left:0}
.node-editor-dialog .upgrade-digest{overflow-wrap:anywhere}
@media(max-width:600px){.node-editor-dialog .form-grid{grid-template-columns:1fr}.node-editor-dialog>.el-dialog__footer .el-button{flex:1 1 auto}}
</style>
<style scoped>.private-key-entry{width:100%;padding:12px;border:1px dashed var(--el-border-color);border-radius:8px}.private-key-actions{display:flex;align-items:center;flex-wrap:wrap;gap:12px;margin-top:10px}</style>
